/**
 * Why the model did not fill the fields a partial label reading left unread.
 */
export type LabelReadingFallbackCause =
  "reader_unavailable" | "load_headroom_refused";

/**
 * Why a draft's label reading stood without its model fill.
 *
 * Kept beside a draft projection, never inside it: the fallback describes the
 * reader, not the document, and a stored draft does not carry it, so folding
 * it into the draft would change the digest a review is bound to.
 *
 * A fill that did not run for want of a picked model also serves the refusal's
 * own sentence and the step that leads to the choice, worded when the
 * projection is built; the stored fallback keeps only the refusal's code.
 */
export type LabelReadingFallbackProjectionV1 = {
  cause: LabelReadingFallbackCause;
  unread_fields: string[];
  reader_error_type: string;
  failed_condition_id: string | null;
  refusal_code: string | null;
  refusal_words: string | null;
  refusal_words_language: OutputLanguage | null;
  next_step: OperationNextStepV1 | null;
};

